import os
import binascii


def import_settings_from_environment_variables(settings):
    """Import settings from environment variables into the settings dict."""
    for key, value in os.environ.items():
        if key.startswith('SYNCSERVER_'):
            setting_key = key[len('SYNCSERVER_'):].lower()
            settings[setting_key] = value
    return settings


def str_to_bool(value):
    """Convert a string to a boolean."""
    if isinstance(value, bool):
        return value
    return value.lower() in ('true', '1', 'yes')


def generate_random_hex_key(num_bytes=32):
    """Generate a random hex key of specified length."""
    return binascii.hexlify(os.urandom(num_bytes)).decode('ascii')
